n("נדיר", "נדיר הוא שם עברי מהמילה נדיר, דבר שאין רבים כמוהו ולכן הוא יקר. השם מבטא את התחושה שהילד מיוחד ואין עוד כמותו. השם ניתן לבנים, והוא נדיר באמת. בצליל הוא קרוב לשמות נדב ונדיב.", ["נדב", "נדיב"])
n("הדרה", "הדרה הוא שם עברי מהמילה הדר, יופי והוד. מאותה מילה באים גם השמות הדר והדרי. הדרה היא גם שם של עיר בשרון. השם ניתן לבנות, והוא נשמע מכובד וחגיגי.", ["הדר"])
n("יוראי", "יוראי הוא שם עברי חדש, וכנראה הוא בא מהמילה יורה, הגשם הראשון של הסתיו. יש שקוראים בו גם את המילים יה ורואי, אלוהים רואה אותי. השם ניתן לבנים, והוא נדיר.", ["רואי"])
n("ריאל", "ריאל הוא שם חדש ונדיר, וכנראה הוא בנוי מהמילים רי ואל. בשפה הספרדית ריאל פירושו מלכותי, והוא גם שם של מטבע. השם ניתן גם לבנים וגם לבנות, והוא נשמע קצר ובינלאומי.", ["אריאל"])
n("מילוא", "מילוא הוא שם מקראי. בספר שמואל המילוא הוא חלק מהביצורים של ירושלים, סוללה שבנה דוד כדי למלא את העיר. השם ניתן לבנים, והוא נדיר. בצליל הוא קרוב לשם האיטלקי מילו.", ["מילו"])
n("עירית", "עירית היא צמח בר עם פרחים לבנים וורודים שפורח באביב בשדות של הארץ. השם עברי, והוא שייך לגל של שמות פרחים שנפוצו בארץ בשנות החמישים והשישים. השם ניתן לבנות.", ["נורית", "כלנית"])
n("אלנה", "אלנה היא צורה של הלנה, שם יווני עתיק שפירושו כנראה זוהרת. השם נפוץ ברוסית, באיטלקית ובשפה הספרדית. בארץ השם הגיע עם העלייה, והוא ניתן לבנות. בעברית הוא נשמע גם קרוב לאלונה.", ["הלנה", "אלונה"])
n("עמירם", "עמירם הוא שם עברי שבנוי מהמילים עמי ורם, ופירושו העם שלי נעלה. השם קרוב לשם המקראי עמרם, אביהם של משה ואהרן. השם ניתן לבנים, והוא היה נפוץ בארץ בשנות הארבעים והחמישים.", ["עמרם", "עמי"])
n("רקפת", "רקפת היא פרח בר ורוד ולבן שפורח בחורף בין הסלעים, ועליו מתכופפים כמו ראש מורכן. השם עברי, והוא היה נפוץ בארץ בשנות החמישים והשישים. השם ניתן לבנות.", ["כלנית", "נורית"])
n("נטשה", "נטשה היא צורת חיבה רוסית של נטליה, שם שבא מהמילה הלטינית נטליס, יום הולדת. השם מוכר בזכות נטשה רוסטובה, הגיבורה של מלחמה ושלום. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", ["נטליה", "נטלי"])
n("נופית", "נופית הוא שם עברי חדש מהמילה נוף, מה שרואים מסביב, וגם צמרת של עץ. השם נשמע רך ופתוח. נופית היא גם שם של יישוב בגליל. השם ניתן לבנות, וקרוב אליו השם נופיה.", ["נופיה"])
n("דניה", "דניה הוא שם עברי שבנוי מהמילים דן ויה, ופירושו אלוהים שופט. מאותו שורש באים גם השמות דן, דניאל ודינה. השם ניתן לבנות, והוא נדיר. בשפות אחרות דניה היא גם צורה של דניאלה.", ["דניאלה", "דן"])
n("זאן", "זאן הוא שם חדש ונדיר, וכנראה הוא צורה של ז׳אן, הצורה הצרפתית של יוחנן, ה׳ חנן. בעברית הצליל שלו קצר וחד. השם ניתן לבנים, והוא נשמע בינלאומי.", ["יוחנן"])
n("אמציה", "אמציה הוא שם מקראי שפירושו אלוהים אימץ, מהמילה אומץ. אמציה היה מלך יהודה, ובספר מלכים מסופר על המלחמות שלו. השם ניתן לבנים, והוא נדיר. קרוב אליו השם אמוץ.", ["אמוץ"])
n("יתיר", "יתיר הוא שם מקראי של עיר בהרי יהודה, שמוזכרת בספר יהושע. בארמית המילה יתיר פירושה יותר או נוסף. יער יתיר הוא היום אחד היערות הגדולים בארץ. השם ניתן לבנים, והוא נדיר.", [])
n("אתגר", "אתגר הוא שם עברי חדש מהמילה אתגר, משימה קשה שדורשת מאמץ. השם מבטא אומץ ורצון להתמודד. יש בו רוח של עשייה ושל רצון ללמוד דברים חדשים. השם ניתן לבנים, והוא נדיר.", [])
n("תמוז", "תמוז הוא שם של חודש הקיץ בלוח העברי, ומקורו בשם של אל בבלי. יש הורים שבוחרים בו לילד שנולד בחודש תמוז. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרובים אליו שמות של חודשים כמו אדר וניסן.", ["אדר", "ניסן"])
n("בנו", "בנו הוא צורת חיבה של בנימין, ובשפות של אירופה גם שם בפני עצמו, כמו בנו באיטלקית. השם בנימין פירושו בן של יד ימין. בארץ השם נדיר, והוא ניתן לבנים.", ["בנימין", "בני"])
n("שימעון", "שימעון הוא כתיב של שמעון, אחד מבני יעקב. השם בא מהשורש ש־מ־ע, ובמסורת לאה קוראת לו כך כי אלוהים שמע את קולה. השם ניתן לבנים, והכתיב הזה נדיר בארץ.", ["שמעון"])
n("פארי", "פארי הוא שם עברי חדש מהמילה פאר, יופי והדר, ופירושו הפאר שלי. השם נשמע חגיגי וקצר. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרוב אליו השם פאר.", ["פאר"])
n("אלרז", "אלרז הוא שם עברי חדש שבנוי מהמילים אל ורז, ופירושו הסוד של אלוהים. מאותה מילה באים גם השמות רז ואלירז. השם ניתן לבנים, והוא נשמע מודרני ושקט.", ["אלירז", "רז"])
n("פאי", "פאי הוא שם קצר ונדיר, ואולי הוא קיצור של שמות כמו פאינה. באנגלית פאי הוא גם שם של אות יוונית. השם ניתן לבנות, והוא נשמע קליל ובינלאומי.", ["פאינה"])
n("כרמית", "כרמית הוא שם עברי מהמילה כרם, שדה של גפנים. מאותה מילה באים גם השמות כרמל וכרמי. השם היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנות.", ["כרמל", "כרמי"])
n("צדוק", "צדוק הוא שם מקראי מהמילה צדק. צדוק היה הכוהן הגדול בימי דוד ושלמה, ובספר שמואל הוא מוזכר בין שרי דוד. מצאצאיו באו בני צדוק, הכוהנים. השם ניתן לבנים, והוא נפוץ בעיקר בקהילות של יהודי תימן.", ["צדק"])
n("סוזנה", "סוזנה היא צורה אירופית של שושנה, שם עברי שפירושו פרח השושן. השם נפוץ באיטלקית, בשפה הספרדית ובפורטוגזית. בארץ הוא נדיר, והוא ניתן לבנות. מוכרת גם הצורה סוזן.", ["סוזן", "שושנה"])
n("פלורה", "פלורה היא המילה הלטינית לפרח, וגם שמה של אלת הפרחים והאביב במיתולוגיה הרומית. השם היה נפוץ בקהילות של יהודי יוון, תורכיה ובלקן. השם ניתן לבנות, והוא נדיר היום.", [])
n("איבון", "איבון הוא שם צרפתי, הצורה הנשית של איב, שמקורו בגרמנית עתיקה, ויש שקושרים אותו לעץ הטקסוס. השם היה נפוץ בצרפת באמצע המאה העשרים. בארץ הוא נדיר, והוא ניתן לבנות.", [])
n("קארן", "קארן היא צורה סקנדינבית של קתרין, שבאה כנראה מהמילה היוונית קתרוס, טהור. השם נפוץ באנגלית ובשפות הצפון. בעברית קרן היא גם קרן אור, ולכן השם נשמע מוכר. השם ניתן לבנות.", ["קרן", "קארין"])
n("צופית", "צופית היא ציפור קטנה וצבעונית שיונקת צוף מפרחים, ונוצות הזכר מבריקות בירוק ובסגול. השם עברי, והוא קשור גם למילה צוף. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["צופיה"])
n("שושי", "שושי היא צורת חיבה של שושנה, שם עברי שפירושו פרח השושן. השם היה נפוץ בארץ בשנות החמישים, והוא ניתן לבנות. מוכרות גם הצורות שושה ושושנה.", ["שושנה"])
n("כלנית", "כלנית היא פרח בר אדום שפורח בחורף ומכסה את השדות בדרום. השם עברי, והוא שייך לגל של שמות פרחים שנפוצו בארץ בשנות החמישים, כמו רקפת ונורית. בסקר ציבורי גדול נבחרה הכלנית לפרח הלאומי של ישראל. השם ניתן לבנות.", ["רקפת", "נורית"])
n("נרקיס", "נרקיס הוא פרח בר לבן וריחני שפורח בחורף בעמקים ובחוף. השם עברי, והוא נשמע עדין ושונה. במיתולוגיה היוונית נרקיס הוא נער שהתאהב בבבואה שלו. השם ניתן לבנות, והוא נדיר.", ["רקפת"])
n("אניה", "אניה היא צורת חיבה רוסית של אנה, שבאה מהשם העברי חנה, שפירושו חן. השם נפוץ ברוסית ובפולנית. בארץ השם הגיע עם העלייה, והוא ניתן לבנות. בעברית המילה אניה היא גם ספינה.", ["אנה", "חנה"])
n("גיתית", "גיתית הוא שם של כלי נגינה עתיק, שמוזכר במזמורים שבהם הלוויים שרו. השם קשור גם למילה גת, המקום שבו דורכים ענבים. השם ניתן לבנות, והוא נדיר. קרוב אליו השם גתית.", ["גתית", "גת"])
n("גואל", "גואל הוא שם עברי מהמילה גואל, מושיע ומשחרר. במסורת היהודית הגאולה היא תקווה גדולה. השם ניתן לבנים, והוא נדיר. מאותו שורש באים גם השמות גאולה וגאל.", ["גאולה", "גאל"])
n("אמוץ", "אמוץ הוא שם מקראי מהמילה אומץ. בספר ישעיהו אמוץ הוא אביו של ישעיהו הנביא. השם ניתן לבנים, והוא נדיר. מאותה מילה בא גם השם אמציה, וקרוב אליו בצליל השם עמוס.", ["אמציה"])
n("עילית", "עילית הוא שם עברי מהמילה עילוי, ופירושו הטובה ביותר או זו שמעל. השם נשמע גבוה ובהיר. עילית ניתן לבנות, והוא נדיר. מאותו שורש באים גם השמות עילי ועלית.", ["עילי", "עלית"])
n("צורית", "צורית הוא שם עברי מהמילה צור, סלע חזק. השם מביא תמונה של יציבות. צורית היא גם שם של יישוב בגליל. השם ניתן לבנות, וקרובים אליו השמות צור, צוריה וצוריאל.", ["צור", "צוריה"])
n("נבות", "נבות הוא שם מקראי. בספר מלכים נבות היזרעאלי סירב למכור את הכרם שלו למלך אחאב, ונהרג בעלילה. הסיפור הפך לסמל של עוול שעושה השלטון. השם ניתן לבנים, והוא נדיר.", ["נבו"])
n("רע", "רע הוא מילה עברית עתיקה לחבר. בספר משלי נאמר שהרע אוהב בכל עת. השם קצר מאוד, והוא ניתן לבנים. הוא נדיר, וקרובים אליו השמות רעי ורועי, ושם הנקבה רעות.", ["רעי", "רעות"])
n("תניא", "תניא היא מילה ארמית שפירושה נלמד או שנינו. זה גם שמו של ספר יסוד של חסידות חב״ד, שכתב רבי שניאור זלמן מלאדי. השם ניתן לבנות, והוא נפוץ בעיקר בקהילות חב״ד. מוכר גם הכתיב תניה.", ["תניה"])
n("אלדן", "אלדן הוא שם עברי חדש שבנוי מהמילים אל ודן, ופירושו אלוהים שופט. באנגלית אלדן הוא גם שם ממקור אנגלי עתיק. השם ניתן לבנים, והוא נדיר.", ["אלדנה", "דן"])
n("חדווה", "חדווה הוא שם עברי מהמילה חדווה, שמחה גדולה. השם היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות. מוכר גם הכתיב חדוה. יש בו תחושה של שמחה פשוטה.", ["חדוה"])
n("גליל", "גליל הוא שם עברי מהמילה גליל, האזור ההררי בצפון הארץ. השם מביא תמונה של הרים, מעיינות וירוק. השם ניתן לבנים, והוא נדיר. קרובה אליו צורת הנקבה גלילה.", ["גלילה"])
n("מתיתיהו", "מתיתיהו הוא שם עברי שפירושו מתנת ה׳. מתתיהו הכהן היה אביהם של המכבים, שמרדו ביוונים, ובזכותו חוגגים את חנוכה. השם ניתן לבנים, והוא נפוץ בעיקר בקהילות דתיות.", ["מתתיהו"])
n("מאלי", "מאלי הוא שם חדש ונדיר, וכנראה הוא צורת חיבה של מלכה או של מאיה. מאלי היא גם שם של מדינה במערב אפריקה. השם ניתן לבנות, והוא נשמע קצר וחם.", ["מלכה", "מאילי"])
n("גדיאל", "גדיאל הוא שם מקראי. בספר במדבר גדיאל בן סודי הוא אחד משנים עשר המרגלים ששלח משה, משבט זבולון. השם קשור למילה גד, מזל טוב. השם ניתן לבנים, והוא נדיר.", ["גד", "גדי"])
n("ירמי", "ירמי הוא צורת חיבה של ירמיהו, אחד הנביאים הגדולים. השם ירמיהו פירושו כנראה ה׳ ירומם. ירמי היה מוכר בארץ בשנות הארבעים והחמישים, והוא ניתן לבנים.", ["ירמיהו"])
n("צרויה", "צרויה היא אחותו של דוד המלך ואמם של יואב, אבישי ועשהאל. בספר שמואל בניה נקראים תמיד בני צרויה, על שם אמם. השם ניתן לבנות, והוא נדיר.", [])
n("נוריה", "נוריה הוא שם עברי שבנוי מהמילים נור ויה, ופירושו האש של אלוהים. מאותה מילה באים גם השמות נורית ונוריאל. השם ניתן לבנות, והוא נדיר.", ["נוריאל", "נורית"])
